const maxFill = (grid, capacity) => {
    // create a dp array of the same size of grid
    let dp = Array(grid.length).fill(0).map(x => Array(grid[0].length).fill(0));
    for(let i = 0; i < grid.length; i++){
        for(let j = 0; j < grid[0].length; j++){
            // 1 means there is water in the well, 
            // add it to the current bucket capacity
            if(grid[i][j] === 1){
                dp[i][j] = 1;
            }
            // if we are not on the first row, 
            // add the previous row to the current bucket capacity
            if(i > 0){
                dp[i][j] += dp[i-1][j];
            }
            // if we are not on the first column, 
            // add the previous column to the current bucket capacity
            if(j > 0){
                dp[i][j] += dp[i][j-1];
            }
            // if we are not on the first row and first column, 
            // remove the square in the diagonal, 
            // because we added it twice
            if(i > 0 && j > 0){
                dp[i][j] -= dp[i-1][j-1];
            }
            // compare with the bucket capacity
            dp[i][j] = Math.min(dp[i][j], capacity);
        }
    }
    return dp[grid.length-1][grid[0].length-1];
}

