const correctBracketing = (brackets) => {
    if (brackets.length % 2 !== 0){
        return false;
    }
    const opening_brackets = '([{';
    const closing_brackets = ')]}';
    const matching_brackets = {
        ')': '(',
        ']': '[',
        '}': '{'
    };
    const stack = [];
    for (let i = 0; i < brackets.length; i++){
        if (opening_brackets.includes(brackets[i])){
            stack.push(brackets[i]);
        }
        else if (closing_brackets.includes(brackets[i])){
            if (stack.length === 0){
                return false;
            }
            else if (stack[stack.length - 1] === matching_brackets[brackets[i]]){
                stack.pop();
            }
            else {
                return false;
            }
        }
    }
    return stack.length === 0;
}

