	for (var i = 0; i < digits.length; i++) {
		var digit = digits[i];
		var power = Math.pow(10, i);
		switch (digit) {
			case '4': result = characters[power] + characters[power * 5] + result; break;
			case '9': result = characters[power] + characters[power * 10] + result; break;
			default:
				if (digit < 4) {
					result = new Array(parseInt(digit) + 1).join(characters[power]) + result;
				} else if (digit >= 5) {
					result = characters[power * 5] + new Array(parseInt(digit) - 4).join(characters[power]) + result;
				}
		}
	}
	return result;
}

