const hasCloseElements = (numbers, threshold) => {
    if(numbers.length <= 1){
		return false;
	}

	var numbersSorted = numbers.sort();
	var currentNumber = numbersSorted[0];
	var closestDifference = threshold + 1;

	for(var i = 1; i < numbersSorted.length; i++){
		var currentDifference = Math.abs(currentNumber - numbersSorted[i]);
		if(currentDifference < closestDifference){
			closestDifference = currentDifference;
		}
		currentNumber = numbersSorted[i];
	}

	return closestDifference < threshold;
}

