const isNested = (string) => {
    let openBracket=['[','{','('];
    let closingBracket=[')','}',']'];
    let openingStack=[];
    let checkingResult=0;
    for(let i=0;i<string.length;i++){
        if(openBracket.includes(string[i])){
            openingStack.push(string[i]);
        }
        else if(closingBracket.includes(string[i])){
            if(openBracket.indexOf(openingStack[openingStack.length-1])===closingBracket.indexOf(string[i])){
                openingStack.pop();
            }
            else{
                checkingResult=1;
                break;
            }
        }
    }
    if(checkingResult==1 || openingStack.length!=0){
        return false;
    }
    else{
        return true;
    }
}

