    var valueArray = [];
    // convert each element of arr to binary and store into binaryArray
    for(var i = 0; i < arr.length; i++){
        binaryArray.push(arr[i].toString(2));
    }
    //push values of arr into valueArray
    for(var i = 0; i < arr.length; i++){
        valueArray.push(arr[i]);
    }
    // use bubble sort to sort binaryArray in ascending order
    for(var i = 0; i < binaryArray.length; i++){
        for(var j = 0; j < binaryArray.length; j++){
            if(binaryArray[j].match(/1/g).length > binaryArray[j+1].match(/1/g).length){
                var tmp = binaryArray[j];
                binaryArray[j] = binaryArray[j+1];
                binaryArray[j+1] = tmp;
                var tmp = valueArray[j];
                valueArray[j] = valueArray[j+1];
                valueArray[j+1] = tmp;
