const getOddCollatz = (n) => {
    if(n === 1) {
		return [1];
	}
	let nums = [n];
	while(n !== 1) {
		if(n % 2 === 0) {
			n = n / 2;
		} else {
			n = (3 * n) + 1;
		}
		nums.push(n);
	}
	return nums.filter(n => n % 2 !== 0);
}

