const strangeSortList = (lst) => {
    let asc = [...lst].sort((a, b) => a - b);
    let desc = [...lst].sort((a, b) => b - a);
    let flag = true;
    let result = [];
    while (asc.length > 0) {
        if (flag) {
            result.push(asc.shift());
        } else {
            result.push(desc.shift());
        }
        flag = !flag;
    }
    return result;
}

