const getMaxTriples = (n) => {
    let sum = 0
    for(let i = 0; i < n; i++){
        for(let j = i + 1; j < n; j++){
            for(let k = j + 1; k < n; k++){
                let val1 = i * i - i + 1
                let val2 = j * j - j + 1
                let val3 = k * k - k + 1
                if((val1 + val2 + val3) % 3 === 0){
                    sum++
                }
            }
        }
    }
    return sum
}

