const separateParenGroups = (paren_string) => {
    var paren_groups = [];
  var paren_stack = [];
  var last_paren = null;
  var paren_count = 0;
  var last_paren_idx = 0;
  for (var i = 0; i < paren_string.length; i++) {
    var c = paren_string[i];
    if (c === '(' || c === ')') {
      if (last_paren && c !== last_paren) {
        paren_stack.push(c);
        last_paren = c;
        paren_count++;
      } else if (last_paren && c === last_paren) {
        paren_stack.pop();
        last_paren = paren_stack[paren_stack.length - 1];
        paren_count++;
      } else {
        last_paren = c;
        paren_count++;
      }
    }

    if (paren_count % 2 === 0) {
      paren_groups.push(paren_string.slice(last_paren_idx, i + 1));
      last_paren_idx = i + 1;
    }
  }
  return paren_groups;
}

