        if(split_paren_string[i][0] === '('){
            current_group += split_paren_string[i];
            //if the current group is not balanced, add the next item to it.
            if(current_group.length % 2 !== 0){
                current_group += split_paren_string[i + 1];
                i++;
            }
            //push the current group to our groups list.
            groups.push(current_group);
        }
    }
    return groups;
}

