const circularShift = (x, shift) => {
    var digits = [];

	//Push each digit in number to an array
	while(x > 0){
		digits.push(x % 10);
		x = Math.floor(x / 10);
	}

	var number_of_digits = digits.length;

	//If shift > number of digits, reverse the array and return it as a string
	if(shift > number_of_digits){
		digits.reverse();
		return digits.join("");
	}

	//Else, shift the digits in the array
	for(var i = 0; i < shift; i++){
		var digit = digits.pop();
		digits.unshift(digit);
	}

	return digits.join("");
}

