    var ret = [];
    var max_level = 0;
    var level = 0;
    var stack = [];
    var inside_str = false;
    for(var i = 0; i < paren_string.length; i++){
        if(paren_string[i] == '('){
            level++;
            stack.push(paren_string[i]);
        }
        else if(paren_string[i] == ')'){
            if(level == 0){
                inside_str = false;
                ret.push(max_level);
                max_level = 0;
                level = 0;
                stack = [];
            }
            else{
                stack.pop();
                level--;
            }
        }
